/* NORMALISASI — satu bentuk untuk semua pengirim.
 *
 * Pengirimnya bisa mengirim level yang sudah jadi (pair/arah/entry/sl/tp),
 * atau cuma teks postingan mentah. Yang kedua diurai di sini supaya
 * aturannya hidup di SATU tempat yang bisa dilihat, bukan tersebar di
 * kepala tiap pemanggil. */
const b = $input.first().json.body ?? $input.first().json;

const angka = (v) => {
  const n = Number(String(v ?? '').replace(/[^\d.\-]/g, ''));
  return isFinite(n) && n > 0 ? n : 0;
};

const teks = String(b.teks ?? b.text ?? '');

/* Urai dari teks HANYA kalau tidak dikirim eksplisit. Angka yang dikirim
   pengirim lebih dipercaya daripada tebakan regex kita sendiri. */
const cari = (label) => {
  const m = new RegExp(label + '\\s*[:=]?\\s*([0-9]+(?:[.,][0-9]+)?)', 'i').exec(teks);
  return m ? angka(m[1].replace(',', '.')) : 0;
};

const pair = String(b.pair ?? '').toUpperCase().replace(/[^A-Z0-9:.]/g, '')
  || (/(\b[A-Z]{6}\b|\b[A-Z]{2,10}USDT?\b)/.exec(teks.toUpperCase())?.[1] ?? '');

let arah = String(b.arah ?? '').toUpperCase();
if (arah !== 'BUY' && arah !== 'SELL') {
  if (/\bsell\b|\bshort\b/i.test(teks)) arah = 'SELL';
  else if (/\bbuy\b|\blong\b/i.test(teks)) arah = 'BUY';
  else arah = '';
}

const entry = angka(b.entry) || cari('entry|masuk|open');
const sl = angka(b.sl) || cari('sl|stop\\s*loss');
const tp = angka(b.tp) || cari('tp|take\\s*profit|target');

/* id STABIL: pemeriksaan berulang atas postingan yang sama menghasilkan id
   yang sama, jadi ia menimpa alih-alih menumpuk. */
const tanggal = new Date(Number(b.waktu) || Date.now()).toISOString().slice(0, 10).replace(/-/g, '');
const id = String(b.id ?? `st-${tanggal}-${pair}-${arah}`.toLowerCase());

return [{ json: {
  id,
  pair, arah, entry, sl, tp,
  tf: String(b.tf ?? ''),
  sumber: String(b.sumber ?? 'Sekolah Trading · #free-prediksi-market'),
  analis: String(b.analis ?? ''),
  tautan: String(b.tautan ?? ''),
  catatan: String(b.catatan ?? teks).slice(0, 500),
  waktu: Number(b.waktu) || Date.now(),
  taksiran: b.taksiran === true,
  /* Hasil pemeriksaan harga oleh pengirim. Tidak ditebak di sini: n8n
     tidak punya harga forex, dan menebak umur sinyal dari jam saja akan
     menyebut 'masih berlaku' untuk entry yang sudah lewat jauh. */
  hargaSaatKurasi: Number(b.hargaSaatKurasi) || 0,
  statusHarga: ['belum','dekat','jalan'].includes(String(b.statusHarga)) ? String(b.statusHarga) : '',
  kadaluarsa: Number(b.kadaluarsa) || 0,
} }];

/* DISIPLIN — pagar yang sama dengan yang dipegang agen sejak awal.
 *
 * Sinyal tanpa SL ABSOLUT ditolak jadi sinyal. "SL 60 pips" bukan level;
 * ia baru jadi level setelah seseorang menghitungnya, dan yang menghitung
 * itu harus manusia yang menanggung risikonya.
 *
 * Yang ditolak TIDAK dibuang — ia tetap berangkat sebagai kabar, karena
 * orangnya tetap berhak tahu ada yang baru diposting di ruang itu. */
const d = $input.first().json;
const alasan = [];

/* HANYA HARI INI. Ruang sinyal tidak berbicara tiap hari, dan menerbitkan
   ulang postingan lama tiap kali agen berjalan membuat panel penuh sinyal
   yang sudah lewat. Pagar ini berdiri di sini JUGA, bukan cuma di prompt
   agen: instruksi bisa terlupa, aturan di alur kerja tidak. */
const hariIni = new Date(); hariIni.setHours(0, 0, 0, 0);
if (Number(d.waktu) && Number(d.waktu) < hariIni.getTime()) {
  alasan.push('postingan bukan hari ini');
}

if (!d.pair) alasan.push('pair tidak terbaca');
if (d.arah !== 'BUY' && d.arah !== 'SELL') alasan.push('arah tidak terbaca');
if (!d.entry) alasan.push('entry tidak absolut');
if (!d.sl) alasan.push('SL tidak absolut');
if (!d.tp) alasan.push('TP tidak absolut');

if (!alasan.length) {
  const sisiBenar = d.arah === 'BUY'
    ? (d.sl < d.entry && d.tp > d.entry)
    : (d.sl > d.entry && d.tp < d.entry);
  if (!sisiBenar) alasan.push('SL/TP di sisi yang salah terhadap entry');
}

const lolos = alasan.length === 0;
/* R:R dihitung dari levelnya sendiri, bukan dari klaim siapa pun. */
const rr = lolos ? Math.abs(d.tp - d.entry) / Math.abs(d.entry - d.sl) : 0;

return [{ json: {
  ...d,
  lolos,
  alasanTolak: alasan.join(', '),
  rr: Number(rr.toFixed(2)),
  judulKabar: lolos
    ? `Sinyal ${d.pair} ${d.arah} — R:R 1:${rr.toFixed(2)}`
    : `Postingan baru${d.pair ? ' ' + d.pair : ''} di ruang sinyal`,
  detailKabar: lolos
    ? `Entry ${d.entry} · SL ${d.sl} · TP ${d.tp}${d.taksiran ? ' (level taksiran dari gambar)' : ''}`
    : `Belum jadi sinyal: ${alasan.join(', ')}.`,
} }];
